//! Interop Envelope tokens made by the real Laravel encrypter and the `laravel-interop` package
//! (`fixtures/envelope-vectors.json`, regenerated by `bin/generate-vectors.php` of that package).
//! Every vector names the verdict all implementations have to reach.

use base64::engine::general_purpose::STANDARD;
use base64::Engine as _;
use laravel_rust_encryption::{Cipher, Encrypter, OpenOptions, Opened};
use serde_json::Value as Json;

fn fixtures() -> Json {
    let data = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/envelope-vectors.json"
    ))
    .expect("read fixtures/envelope-vectors.json");
    serde_json::from_str(&data).expect("parse fixtures/envelope-vectors.json")
}

fn key(fx: &Json, field: &str, cipher: Cipher) -> Vec<u8> {
    STANDARD.decode(fx[field].as_str().unwrap()).unwrap()[..cipher.key_size()].to_vec()
}

/// The encrypter of an application that did not (`rotated = false`) or did rotate its key.
fn encrypter(fx: &Json, cipher: Cipher, rotated: bool) -> Encrypter {
    let enc = Encrypter::new(&key(fx, "key_b64", cipher), cipher).unwrap();
    if rotated {
        enc.with_previous_keys([key(fx, "previous_key_b64", cipher)])
            .unwrap()
    } else {
        enc
    }
}

fn options(v: &Json) -> OpenOptions {
    OpenOptions::default()
        .leeway(v["leeway"].as_u64().unwrap().try_into().unwrap())
        .now(v["now"].as_i64().unwrap())
}

/// The verdict name, or the opened envelope.
fn judge(enc: &Encrypter, token: &str, v: &Json) -> Result<Opened, &'static str> {
    enc.open_envelope_with(token, v["scope"].as_str().unwrap(), options(v))
        .map_err(|e| e.kind())
}

fn check(v: &Json, got: Result<Opened, &'static str>, context: &str) {
    let name = format!("{context}{} {}", v["cipher"], v["name"]);
    let expect = v["expect"].as_str().unwrap();
    match got {
        Ok(opened) => {
            assert_eq!(expect, "ok", "{name}: opened, expected {expect}");
            assert_eq!(opened.issued_at, v["iat"].as_i64().unwrap(), "{name}");
            assert_eq!(opened.not_before, v["nbf"].as_i64(), "{name}");
            assert_eq!(opened.expires_at, v["exp"].as_i64(), "{name}");
            assert_eq!(opened.data, v["data"], "{name}");
            assert_eq!(opened.scope, v["scope"].as_str().unwrap(), "{name}");
        }
        Err(kind) => assert_eq!(kind, expect, "{name}"),
    }
}

#[test]
fn every_vector_gets_the_verdict_the_laravel_package_gives() {
    let fx = fixtures();
    let vectors = fx["vectors"].as_array().unwrap();
    assert!(vectors.len() >= 150);
    for v in vectors {
        let cipher: Cipher = v["cipher"].as_str().unwrap().parse().unwrap();
        let rotated = v["key"] == "previous";
        let enc = encrypter(&fx, cipher, rotated);
        check(v, judge(&enc, v["token"].as_str().unwrap(), v), "");

        if let Some(without) = v["expect_without_previous_key"].as_str() {
            let plain = encrypter(&fx, cipher, false);
            assert_eq!(
                judge(&plain, v["token"].as_str().unwrap(), v).unwrap_err(),
                without,
                "{}",
                v["name"]
            );
        }
    }
}

/// The same documents, encrypted by this crate, get the same verdicts: the envelope rules do not
/// depend on who encrypted.
#[test]
fn the_same_documents_encrypted_here_get_the_same_verdicts() {
    let fx = fixtures();
    let mut checked = 0;
    for v in fx["vectors"].as_array().unwrap() {
        let Some(plaintext) = v["plaintext_b64"].as_str() else {
            continue;
        };
        if v["key"] != "current" || v["expect"] == "decrypt_error" {
            continue;
        }
        let cipher: Cipher = v["cipher"].as_str().unwrap().parse().unwrap();
        let enc = encrypter(&fx, cipher, false);
        let token = enc
            .encrypt_bytes(&STANDARD.decode(plaintext).unwrap())
            .unwrap();
        check(v, judge(&enc, &token, v), "re-encrypted ");
        checked += 1;
    }
    assert!(checked >= 120, "only {checked} vectors re-encrypted");
}

#[test]
fn tokens_that_are_not_envelopes_are_invalid_not_decrypt_errors() {
    let fx = fixtures();
    let enc = encrypter(&fx, Cipher::Aes256Cbc, false);
    for token in [
        enc.encrypt_string("hello").unwrap(),
        enc.encrypt_cookie("laravel_session", "abc").unwrap(),
        enc.encrypt(&laravel_rust_encryption::Value::from("hello"))
            .unwrap(),
    ] {
        assert_eq!(
            enc.open_envelope(&token, "s").unwrap_err().kind(),
            "invalid"
        );
    }
}
